import SkeletonService from '../../../../../src/services/SkeletonService';
import { getCollection } from '../../../../../src/lib/mongodb';
import DataService from '../../../../../src/services/DataService';
import { ObjectId } from 'mongodb';

/**
 * ShowEditCtrl - Laravel ShowEditCtrl.php equivalent
 * Renders popup form for editing existing records
 * Auto-generated by ModuleGenerator
 */
export default class ShowEditCtrl {
  /**
   * index method - Main handler
   * @param {Request} req 
   * @param {Response} res 
   * @returns {Promise<Response>}
   */
  async index(req, res) {
    try {
      console.log('🎯 ShowEditCtrl::index() called');

      // Token comes from URL params (set by [token].js route handler)
      const token = req.params?.token || req.body?.skeleton_token || req.query?.token;
      const recordId = req.query?.id || req.body?.id;
      
      if (!token) {
        console.error('❌ No token found:', { params: req.params, body: req.body, query: req.query });
        return res.status(400).json({
          status: false,
          title: 'Token Missing',
          message: 'No token was provided.'
        });
      }
      
      console.log('🔍 Token extracted:', token, 'Record ID:', recordId);

      // Resolve token
      const reqSet = await SkeletonService.resolveToken(token);
      
      if (!reqSet || !reqSet.status || !reqSet.key || !recordId) {
        console.error('❌ Invalid request:', { hasReqSet: !!reqSet, hasKey: !!reqSet?.key, hasRecordId: !!recordId });
        return res.status(400).json({
          status: false,
          title: 'Invalid Token',
          message: 'The provided token is invalid or missing required data (key, recordId).'
        });
      }

      console.log(`📋 Fetching record: table=${reqSet.table}, system=${reqSet.system}, id=${recordId}`);

      // Fetch existing data - users collection can be queried by _id (ObjectId) or user_id (string)
      // Use system from token config, default to 'central'
      const system = reqSet.system || 'central';
      const collection = await getCollection(reqSet.table, system);
      let data = null;
      
      // Try _id first (if it's a valid ObjectId)
      if (ObjectId.isValid(recordId)) {
        try {
          data = await collection.findOne({ _id: new ObjectId(recordId) });
        } catch (e) {
          console.log('⚠️ Failed to query by _id, trying user_id...');
        }
      }
      
      // If not found by _id, try user_id (string field)
      if (!data) {
        data = await collection.findOne({ user_id: recordId });
      }
      
      // If still not found, try username as fallback
      if (!data) {
        data = await collection.findOne({ username: recordId });
      }

      if (!data) {
        console.error('❌ Record not found:', { recordId, table: reqSet.table, system: reqSet.system });
        return res.status(404).json({
          status: false,
          title: 'Record Not Found',
          message: 'The requested record was not found.'
        });
      }
      
      console.log('✅ Record found:', { _id: data._id, user_id: data.user_id, username: data.username });

      let popup = {};

      // Handle different configuration keys
      switch (reqSet.key) {
        case 'central_querynest':
          // TODO: Configure your form fields with existing data
          popup = {
            form: 'builder',
            labelType: 'floating',
            fields: [
              {
                type: 'text',
                name: 'name',
                label: 'Name',
                required: true,
                col: 12,
                value: data.name || '',
                attr: { 'maxlength': '100' }
              }
              // TODO: Add more form fields with data values
            ],
            type: 'modal',
            size: 'md',
            position: 'end',
            label: '<i class="fa-regular fa-folder me-1"></i> Edit querynest',
            short_label: '',
            button: 'Update',
            script: 'window.general.select();'
          };
          break;

        case 'central_users_addusers':
          // User edit form fields matching users collection schema
          popup = {
            form: 'builder',
            labelType: 'floating',
            fields: [
              {
                type: 'text',
                name: 'username',
                label: 'Username',
                value: data.username || '',
                required: true,
                col: 6,
                attr: { 'maxlength': '100' }
              },
              {
                type: 'email',
                name: 'email',
                label: 'Email',
                value: data.email || '',
                required: false,
                col: 6,
                attr: { 'maxlength': '255' }
              },
              {
                type: 'text',
                name: 'first_name',
                label: 'First Name',
                value: data.first_name || '',
                required: false,
                col: 6,
                attr: { 'maxlength': '255' }
              },
              {
                type: 'text',
                name: 'last_name',
                label: 'Last Name',
                value: data.last_name || '',
                required: false,
                col: 6,
                attr: { 'maxlength': '255' }
              },
              {
                type: 'text',
                name: 'phone',
                label: 'Phone',
                value: data.phone || '',
                required: false,
                col: 6,
                attr: { 'maxlength': '50' }
              },
              {
                type: 'select',
                name: 'role',
                label: 'Role',
                options: { 'user': 'User', 'admin': 'Admin' },
                value: data.role || 'user',
                required: true,
                col: 6
              },
              {
                type: 'select',
                name: 'account_status',
                label: 'Status',
                options: { 'active': 'Active', 'deactive': 'Deactive' },
                value: data.account_status || 'active',
                required: true,
                col: 6
              },
              {
                type: 'file',
                name: 'profile',
                label: 'Profile Image',
                value: data.profile || '',
                required: false,
                col: 6,
                helpText: 'Optional: Upload profile image (max 10MB)'
              },
              {
                type: 'file',
                name: 'cover',
                label: 'Cover Image',
                value: data.cover || '',
                required: false,
                col: 6,
                helpText: 'Optional: Upload cover image (max 10MB)'
              }
            ],
            type: 'modal',
            size: 'lg',
            position: 'end',
            label: '<i class="fa-regular fa-user me-1"></i> Edit User',
            button: 'Update User',
            script: 'window.general.select();'
          };
          break;

        default:
      return res.status(400).json({
        status: false,
            title: 'Invalid Configuration',
            message: 'The configuration key is not supported.'
      });
    }

      // Structure response for DynamicModal component
      const responseData = {
        fields: popup.fields || [],
        labelType: popup.labelType || 'floating',
        modal: {
          size: popup.size || 'lg',
          title: popup.label || 'Form',
          button: popup.button || 'Update'
        },
        script: popup.script || '',
        validate: reqSet.validate || '0'
      };

      return res.status(200).json({
        status: true,
        title: 'Form Generated',
        message: `Edit form for ${reqSet.key} generated successfully.`,
        data: responseData
      });

    } catch (error) {
      console.error('❌ ShowEditCtrl error:', error);
      return res.status(500).json({
        status: false,
        title: 'Error',
        message: 'An error occurred while processing the request.'
      });
    }
  }
}
